"use client";
import Component from "../kokonut/MouseEffectCard";
import { useState } from "react";
import { DemoFrame } from "../shared/DemoFrame";

export default function Demo() {
  const [message, setMessage] = useState("");
  return (
    <DemoFrame className="min-h-[420px] p-0 gap-0" hint={message}>
      <div
        className="w-full shrink-0 scale-[.84] flex justify-center"
        onClick={(event) => {
          const action = (event.target as HTMLElement).closest("a");
          if (action) {
            event.preventDefault();
            setMessage(`${action.textContent} selected in this demo.`);
          }
        }}
      >
        <Component />
      </div>
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

